// TypeScript: json-schema-to-typescript types + ajv standalone validators.
import standaloneModule from "ajv/dist/standalone/index.js";
import { compile } from "json-schema-to-typescript";
import { addAllSchemas, makeAjv } from "./ajv.mjs";
import { buildBundle } from "./bundle.mjs";
import { typeRef } from "./schemas.mjs";

const standaloneCode = standaloneModule.default ?? standaloneModule;

export const HEADER =
  "Generated by packages/contracts/scripts/gen.mjs from packages/contracts/schemas. Do not edit; run `npm run -w @plinth/contracts gen`.";

// ajv runtime helpers inlined so the module has no deep imports into ajv.
const RUNTIME = {
  "ajv/dist/runtime/ucs2length": `function ucs2length(str) {
  let length = 0;
  let pos = 0;
  while (pos < str.length) {
    length++;
    const value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < str.length) {
      if ((str.charCodeAt(pos) & 0xfc00) === 0xdc00) pos++;
    }
  }
  return length;
}`,
  "ajv/dist/runtime/equal": `function equal(a, b) {
  if (a === b) return true;
  if (a && b && typeof a === "object" && typeof b === "object") {
    if (Array.isArray(a) !== Array.isArray(b)) return false;
    if (Array.isArray(a)) return a.length === b.length && a.every((v, i) => equal(v, b[i]));
    const ka = Object.keys(a);
    if (ka.length !== Object.keys(b).length) return false;
    return ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && equal(a[k], b[k]));
  }
  return a !== a && b !== b;
}`,
};

export async function emitTs(loaded) {
  const files = {};

  // 1. Types.
  const bundle = buildBundle(loaded, "ts");
  let types = await compile(bundle, "PlinthContracts", {
    bannerComment: `/* eslint-disable */\n// ${HEADER}`,
    unreachableDefinitions: true,
    additionalProperties: false,
    strictIndexSignatures: true,
    declareExternallyReferenced: true,
    enableConstEnums: false,
    maxItems: -1,
    format: true,
    style: { printWidth: 100, singleQuote: false, trailingComma: "all" },
  });
  types = types
    .replace(
      /\/\*\*\n \* This interface was referenced by `PlinthContracts`'s JSON-Schema\n \* via the `definition` "[A-Za-z0-9]+"\.\n \*\/\n/g,
      "",
    )
    .replace(
      / \*\n \* This interface was referenced by `PlinthContracts`'s JSON-Schema\n \* via the `definition` "[A-Za-z0-9]+"\.\n/g,
      "",
    )
    .replace(/export interface PlinthContracts \{\n(?:.*\n)*?\}\n/, "");
  for (const name of loaded.types.keys())
    if (!new RegExp(`export (interface|type) ${name}\\b`).test(types))
      throw new Error(`contracts: json-schema-to-typescript did not emit ${name}`);
  files["gen/ts/types.ts"] = types;

  // 2. Validators (ajv standalone, ESM).
  const ajv = addAllSchemas(makeAjv({ standalone: true }), loaded);
  const refs = {};
  for (const name of loaded.exported) refs[`validate${name}`] = typeRef(loaded.types.get(name));
  let code = standaloneCode(ajv, refs);
  const used = new Set();
  code = code.replace(/const (\w+) = require\("([^"]+)"\)\.default;/g, (_, v, mod) => {
    const impl = RUNTIME[mod];
    if (!impl)
      throw new Error(`contracts: standalone validators need ${mod}; inline it in emit-ts.mjs`);
    used.add(mod);
    return `const ${v} = ${/^function (\w+)/.exec(impl)[1]};`;
  });
  const hoisted = [...used].sort().map((mod) => RUNTIME[mod]);
  if (/require\(/.test(code))
    throw new Error("contracts: standalone validators still contain require()");
  code = code.replace(/^"use strict";\n?/, "");
  const ids = Object.entries(loaded.schemaIds).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const registry = [
    "",
    "/** Exported type name → its compiled validator. */",
    "export const VALIDATORS = {",
    ...loaded.exported.map((n) => `  ${n}: validate${n},`),
    "};",
    "",
    '/** Envelope id ("plinth.<type>/<major>") → type name. */',
    "export const SCHEMA_IDS = {",
    ...ids.map(([id, name]) => `  "${id}": "${name}",`),
    "};",
    "",
    "/** Every exported type: payloads, request bodies and acknowledgements. */",
    "export const EXPORTED_TYPES = [",
    ...loaded.exported.map((n) => `  "${n}",`),
    "];",
    "",
    '/** The validator for a payload, picked by its "schema" envelope; undefined if unknown. */',
    "export function validatorForPayload(data) {",
    '  const id = data && typeof data === "object" ? data.schema : undefined;',
    '  const name = typeof id === "string" ? SCHEMA_IDS[id] : undefined;',
    "  return name ? VALIDATORS[name] : undefined;",
    "}",
    "",
  ];
  files["gen/ts/validators.js"] =
    `/* eslint-disable */\n// ${HEADER}\n// ajv standalone code (JSON Schema 2020-12, strict; stops at the first error).\n${hoisted.join("\n")}\n${code}\n${registry.join("\n")}`;

  const dts = [
    `// ${HEADER}`,
    `import type { ValidateFunction } from "ajv";`,
    `import type * as T from "./types";`,
    "",
    ...loaded.exported.map((n) => `export declare const validate${n}: ValidateFunction<T.${n}>;`),
    "",
    "/** Exported type name → payload type. */",
    "export interface TypeByName {",
    ...loaded.exported.map((n) => `  ${n}: T.${n};`),
    "}",
    "",
    "export type ExportedTypeName = keyof TypeByName;",
    "",
    "/** Envelope id → payload type. */",
    "export interface PayloadBySchemaId {",
    ...ids.map(([id, name]) => `  "${id}": T.${name};`),
    "}",
    "",
    "export type SchemaId = keyof PayloadBySchemaId;",
    "",
    "export declare const VALIDATORS: { readonly [N in ExportedTypeName]: ValidateFunction<TypeByName[N]> };",
    "export declare const SCHEMA_IDS: { readonly [I in SchemaId]: ExportedTypeName };",
    "export declare const EXPORTED_TYPES: readonly ExportedTypeName[];",
    "export declare function validatorForPayload(",
    "  data: unknown,",
    "): ValidateFunction<PayloadBySchemaId[SchemaId]> | undefined;",
    "",
  ];
  files["gen/ts/validators.d.ts"] = dts.join("\n");
  return files;
}
